CREATE TABLE d1_migrations (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT UNIQUE, applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL);
CREATE TABLE `life_entries` ( `user_id` text NOT NULL, `entry_date` text NOT NULL, `payload` text NOT NULL, `version` integer NOT NULL, `updated_at` text NOT NULL, PRIMARY KEY(`user_id`, `entry_date`) );
CREATE TABLE `life_profiles` ( `user_id` text PRIMARY KEY NOT NULL, `payload` text NOT NULL, `version` integer NOT NULL, `updated_at` text NOT NULL );
INSERT INTO d1_migrations (name) VALUES ('0000_loud_donald_blake.sql');
CREATE TABLE `life_resources` ( `user_id` text NOT NULL, `kind` text NOT NULL, `resource_id` text NOT NULL, `period` text NOT NULL, `payload` text NOT NULL, `version` integer NOT NULL, `updated_at` text NOT NULL, `active_slot` text, PRIMARY KEY(`user_id`, `kind`, `resource_id`) );
CREATE INDEX `idx_life_resources_period` ON `life_resources` (`user_id`,`kind`,`period`);
CREATE UNIQUE INDEX `idx_life_one_active_workout` ON `life_resources` (`user_id`,`kind`,`active_slot`) WHERE "life_resources"."active_slot" IS NOT NULL;
INSERT INTO d1_migrations (name) VALUES ('0001_adorable_scream.sql');
CREATE TABLE `life_ai_reviews` ( `user_id` text NOT NULL, `request_id` text NOT NULL, `entry_date` text NOT NULL, `revision` integer NOT NULL, `source_version` integer NOT NULL, `predecessor_id` text, `critique` text NOT NULL, `status` text NOT NULL, `input_snapshot` text NOT NULL, `report_text` text, `model` text NOT NULL, `price_version` text NOT NULL, `provider_id` text, `input_tokens` integer, `output_tokens` integer, `thought_tokens` integer, `reserved_micros` integer NOT NULL, `cost_micros` integer, `created_at` text NOT NULL, `finished_at` text, `error_code` text, PRIMARY KEY(`user_id`, `request_id`) );
CREATE UNIQUE INDEX `idx_life_ai_revision` ON `life_ai_reviews` (`user_id`,`entry_date`,`revision`);
CREATE INDEX `idx_life_ai_account_time` ON `life_ai_reviews` (`user_id`,`created_at`);
CREATE INDEX `idx_life_ai_time` ON `life_ai_reviews` (`created_at`);
INSERT INTO d1_migrations (name) VALUES ('0002_blushing_prism.sql');
CREATE TABLE `life_auth_account` ( `id` text PRIMARY KEY NOT NULL, `account_id` text NOT NULL, `provider_id` text NOT NULL, `user_id` text NOT NULL, `access_token` text, `refresh_token` text, `id_token` text, `access_token_expires_at` integer, `refresh_token_expires_at` integer, `scope` text, `password` text, `created_at` integer NOT NULL, `updated_at` integer NOT NULL, FOREIGN KEY (`user_id`) REFERENCES `life_auth_user`(`id`) ON UPDATE no action ON DELETE cascade );
CREATE INDEX `idx_auth_account_user` ON `life_auth_account` (`user_id`);
CREATE UNIQUE INDEX `idx_auth_provider_identity` ON `life_auth_account` (`provider_id`,`account_id`);
CREATE TABLE `life_auth_rate_limit` ( `id` text PRIMARY KEY NOT NULL, `key` text NOT NULL, `count` integer NOT NULL, `last_request` integer NOT NULL );
CREATE UNIQUE INDEX `life_auth_rate_limit_key_unique` ON `life_auth_rate_limit` (`key`);
CREATE TABLE `life_auth_session` ( `id` text PRIMARY KEY NOT NULL, `expires_at` integer NOT NULL, `token` text NOT NULL, `created_at` integer NOT NULL, `updated_at` integer NOT NULL, `ip_address` text, `user_agent` text, `user_id` text NOT NULL, FOREIGN KEY (`user_id`) REFERENCES `life_auth_user`(`id`) ON UPDATE no action ON DELETE cascade );
CREATE UNIQUE INDEX `life_auth_session_token_unique` ON `life_auth_session` (`token`);
CREATE INDEX `idx_auth_session_user` ON `life_auth_session` (`user_id`);
CREATE TABLE `life_auth_user` ( `id` text PRIMARY KEY NOT NULL, `name` text NOT NULL, `email` text NOT NULL, `email_verified` integer DEFAULT false NOT NULL, `image` text, `created_at` integer NOT NULL, `updated_at` integer NOT NULL );
CREATE UNIQUE INDEX `life_auth_user_email_unique` ON `life_auth_user` (`email`);
CREATE TABLE `life_auth_verification` ( `id` text PRIMARY KEY NOT NULL, `identifier` text NOT NULL, `value` text NOT NULL, `expires_at` integer NOT NULL, `created_at` integer NOT NULL, `updated_at` integer NOT NULL );
CREATE INDEX `idx_auth_verification_identifier` ON `life_auth_verification` (`identifier`);
INSERT INTO d1_migrations (name) VALUES ('0003_fancy_dreadnoughts.sql');
CREATE TABLE `life_reminder_outbox` ( `user_id` text NOT NULL, `entry_date` text NOT NULL, `created_at` text NOT NULL, PRIMARY KEY(`user_id`, `entry_date`) );
CREATE TABLE `life_review_jobs` ( `user_id` text NOT NULL, `entry_date` text NOT NULL, `detected_at` text NOT NULL, `timezone` text NOT NULL, `local_time` text NOT NULL, `profile_version` integer NOT NULL, PRIMARY KEY(`user_id`, `entry_date`) );
CREATE TRIGGER life_daily_reminder_intent AFTER INSERT ON life_review_jobs BEGIN INSERT INTO life_reminder_outbox(user_id,entry_date,created_at) VALUES(NEW.user_id,NEW.entry_date,NEW.detected_at) ON CONFLICT DO NOTHING; END;
CREATE VIEW life_daily_job_status AS WITH eligibility AS ( SELECT j.user_id,j.entry_date,j.detected_at,e.version AS source_version, COALESCE(json_extract(p.payload,'$.reviewPreferences.remindersEnabled'),1) AS reminders_enabled, CASE WHEN r.status='complete' THEN 'already-generated' WHEN r.request_id IS NOT NULL THEN 'attention' WHEN p.user_id IS NULL OR COALESCE(json_extract(p.payload,'$.reviewPreferences.daily.enabled'),1)<>1 THEN 'disabled' WHEN e.user_id IS NULL THEN 'missing' WHEN COALESCE(json_extract(e.payload,'$.complete'),0)<>1 OR length(trim(COALESCE(json_extract(e.payload,'$.journal'),'')))=0 OR EXISTS(SELECT 1 FROM json_each(e.payload,'$.habits') h WHERE json_extract(h.value,'$.status')='unrecorded') THEN 'incomplete' ELSE 'ready' END AS state FROM life_review_jobs j LEFT JOIN life_profiles p ON p.user_id=j.user_id LEFT JOIN life_entries e ON e.user_id=j.user_id AND e.entry_date=j.entry_date LEFT JOIN life_ai_reviews r ON r.user_id=j.user_id AND r.entry_date=j.entry_date AND r.revision=1 ) SELECT *,CASE WHEN state IN ('missing','incomplete') AND reminders_enabled=1 AND EXISTS(SELECT 1 FROM life_reminder_outbox o WHERE o.user_id=eligibility.user_id AND o.entry_date=eligibility.entry_date) THEN 1 ELSE 0 END AS reminder_pending FROM eligibility;
INSERT INTO d1_migrations (name) VALUES ('0004_mature_makkari.sql');
SELECT 'LifeApp database ready' AS status, (SELECT COUNT(*) FROM d1_migrations) AS migrations_applied, (SELECT COUNT(*) FROM sqlite_master WHERE type='table' AND name GLOB 'life_*') AS app_tables, (SELECT COUNT(*) FROM sqlite_master WHERE type='trigger' AND name='life_daily_reminder_intent') AS reminder_trigger, (SELECT COUNT(*) FROM sqlite_master WHERE type='view' AND name='life_daily_job_status') AS review_status_view;
